// Process pets and check care requirements
const pets = $input.first().json.data || [];
const careActions = [];

for (const pet of pets) {
  const needs = calculateCareNeeds(pet);

  // Check each care need
  if (needs.hunger.urgent) {
    careActions.push({
      petId: pet.id,
      action: 'feed',
      priority: 'high',
      reason: 'Hunger critical: ' + pet.hunger,
      suggestedFood: pet.favoriteFood
    });
  }

  if (needs.energy.critical) {
    careActions.push({
      petId: pet.id,
      action: 'rest',
      priority: 'high',
      reason: 'Energy exhausted: ' + pet.energy
    });
  }

  if (needs.happiness.low) {
    careActions.push({
      petId: pet.id,
      action: 'play',
      priority: 'medium',
      reason: 'Happiness low: ' + pet.happiness
    });
  }

  if (needs.cleanliness.poor) {
    careActions.push({
      petId: pet.id,
      action: 'groom',
      priority: 'medium',
      reason: 'Cleanliness poor: ' + pet.cleanliness
    });
  }

  // Check training opportunities
  if (needs.training.ready && pet.energy > 40) {
    careActions.push({
      petId: pet.id,
      action: 'train',
      priority: 'low',
      reason: 'Training opportunity'
    });
  }
}

// Sort by priority
const priorityOrder = { high: 0, medium: 1, low: 2 };
careActions.sort((a, b) => priorityOrder[a.priority] - priorityOrder[b.priority]);

// Group by pet for batch processing
const groupedActions = {};
for (const action of careActions) {
  if (!groupedActions[action.petId]) {
    groupedActions[action.petId] = [];
  }
  groupedActions[action.petId].push(action);
}

return { careActions, groupedActions, totalPets: pets.length, actionsGenerated: careActions.length };

function calculateCareNeeds(pet) {
  return {
    hunger: {
      level: pet.hunger || 50,
      urgent: (pet.hunger || 50) < 20,
      low: (pet.hunger || 50) < 50
    },
    energy: {
      level: pet.energy || 100,
      critical: (pet.energy || 100) < 10,
      low: (pet.energy || 100) < 30
    },
    happiness: {
      level: pet.happiness || 75,
      low: (pet.happiness || 75) < 40
    },
    cleanliness: {
      level: pet.cleanliness || 80,
      poor: (pet.cleanliness || 80) < 40
    },
    training: {
      ready: shouldTrain(pet)
    }
  };
}

function shouldTrain(pet) {
  // Check if pet is ready for training
  const timeSinceLastTraining = Date.now() - (pet.lastTrained || 0);
  const hoursSinceTraining = timeSinceLastTraining / (1000 * 60 * 60);

  return hoursSinceTraining >= 4 && // At least 4 hours since last training
         pet.energy > 40 && // Has enough energy
         pet.happiness > 30; // Is in decent mood
}

