// Process grouped care actions
const groupedActions = $input.first().json.groupedActions || {};
const results = [];

for (const [petId, actions] of Object.entries(groupedActions)) {
  // Get pet details
  const petResponse = await $helpers.httpRequest({
    method: 'GET',
    url: `http://localhost:3000/api/pets/${petId}`,
    headers: { 'Content-Type': 'application/json' }
  });

  const pet = petResponse.data;

  // Process actions for this pet
  for (const action of actions) {
    try {
      const result = await executeCareAction(pet, action);
      results.push({
        petId: pet.id,
        petName: pet.name,
        action: action.action,
        success: result.success,
        result: result,
        timestamp: new Date().toISOString()
      });

      // Add delay between actions for same pet
      if (actions.length > 1) {
        await new Promise(resolve => setTimeout(resolve, 1000));
      }
    } catch (error) {
      results.push({
        petId: pet.id,
        petName: pet.name,
        action: action.action,
        success: false,
        error: error.message,
        timestamp: new Date().toISOString()
      });
    }
  }
}

return { processedPets: Object.keys(groupedActions).length, results };

async function executeCareAction(pet, action) {
  const endpoint = `http://localhost:3000/api/pets/${pet.id}/care`;
  const payload = {
    actionType: action.action,
    performer: 'auto_care_system',
    location: pet.currentLocation || 'home',
    timestamp: new Date().toISOString()
  };

  // Add action-specific parameters
  switch (action.action) {
    case 'feed':
      payload.food = action.suggestedFood || 'auto_select';
      payload.amount = 'auto';
      break;
    case 'play':
      payload.activity = 'auto_select';
      payload.duration = 15; // 15 minutes for auto-play
      break;
    case 'train':
      payload.skill = 'auto_select';
      payload.intensity = 'light';
      break;
    case 'rest':
      payload.location = 'auto';
      payload.duration = 30; // 30 minutes for auto-rest
      break;
    case 'groom':
      payload.method = 'auto';
      payload.tools = 'auto';
      break;
  }

  const response = await $helpers.httpRequest({
    method: 'POST',
    url: endpoint,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  return response.data;
}

// No care actions needed - just log the check
const data = $input.first().json;

return {
  message: 'Routine care check completed',
  timestamp: new Date().toISOString(),
  petsChecked: data.totalPets || 0,
  actionsRequired: 0,
  status: 'all_pets_well_cared_for'
};
